public InventLocationId parminventoryLocationIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmSourceFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(InventLocationId));
}

private boolean anyNotAllowedBlankDimInHierarchy(
    InventTable _inventTable,
    InventDim   _inventDim)
{
    return (WHSReservationHierarchyInventDimUtil::getNotAllowedBlankDimInHierarchy(_inventTable, _inventDim) != conNull());
}

/// <summary>
/// MPJ_22974_PBMSProductMDRItemStatusAndPackChange
/// To get sales qty from each invent qty dividing by unit conversion factor
/// </summary>
/// <param name = "_inventSum">inventsum</param>
/// <param name = "_inventDim_ds">inventdim</param>
/// <param name = "_inventQty">qty</param>
/// <returns>Sales qty post conversion</returns>
Public Qty salesQtyCalc(InventSum _inventSum,FormDataSource _inventDim_ds,Qty _inventQty)
{
    InventItemSalesSetup    inventItemSalesSetup;
    InventTable             inventTable;
    UnitOfMeasureConversion unitOfMeasureConversion;
    InventSum               inventSumLoc;
    InventDim               inventDimSales,currentInventDim;
    Qty                     salesQty;
    Common                  inventDimJoined = formJoinedRecord(_inventSum, _inventDim_ds);

    currentInventDim = inventDimJoined;

    select firstonly inventSumLoc
        where inventSumLoc.ItemId == _inventSum.ItemId
             join firstonly inventDimSales where inventDimSales.inventDimId == inventSumLoc.InventDimId
                  && inventDimSales.InventSiteId == currentInventDim.InventSiteId;

    inventItemSalesSetup = InventItemSalesSetup::find(_inventSum.ItemId,inventDimSales.InventDimId);

    inventTable          = InventTable::find(_inventSum.ItemId);

    select firstonly Factor
        from unitOfMeasureConversion
        where unitOfMeasureConversion.Product               == inventTable.Product
            && unitOfMeasureConversion.FromUnitOfMeasure    == UnitOfMeasure::unitOfMeasureIdBySymbol(inventItemSalesSetup.METSalesUnit)
            && unitOfMeasureConversion.ToUnitOfMeasure      == UnitOfMeasure::unitOfMeasureIdBySymbol(inventTable.inventUnitId());

    if(unitOfMeasureConversion.Factor)
    {
        salesQty = _inventQty/unitOfMeasureConversion.Factor;
    }
    else
    {
        salesQty = _inventQty;
    }

    return salesQty;
}

/// <summary>
/// To get purch qty from each invent qty dividing by unit conversion factor
/// </summary>
/// <param name = "_inventSum">inventsum</param>
/// <param name = "_inventDim_ds">inventdim</param>
/// <param name = "_inventQty">qty</param>
/// <returns>Purch qty post conversion</returns>
Public Qty purchQtyCalc(InventSum _inventSum,FormDataSource _inventDim_ds, Qty _inventQty)
{
    InventItemPurchSetup    inventItemPurchSetup;
    InventTable             inventTable;
    UnitOfMeasureConversion unitOfMeasureConversion;
    InventSum               inventSumLoc;
    InventDim               inventDimPurch,currentInventDim;
    Qty                     purchQty;
    Common                  inventDimJoined = formJoinedRecord(_inventSum, _inventDim_ds);

    currentInventDim = inventDimJoined;

    select firstonly inventSumLoc
        where inventSumLoc.ItemId == _inventSum.ItemId
             join firstonly inventDimPurch where inventDimPurch.inventDimId == inventSumLoc.InventDimId
                  && inventDimPurch.InventSiteId == currentInventDim.InventSiteId;

    inventItemPurchSetup = InventItemPurchSetup::find(_inventSum.ItemId,inventDimPurch.InventDimId);

    inventTable          = InventTable::find(_inventSum.ItemId);

    select firstonly Factor
        from unitOfMeasureConversion
        where unitOfMeasureConversion.Product               == inventTable.Product
            && unitOfMeasureConversion.FromUnitOfMeasure    == UnitOfMeasure::unitOfMeasureIdBySymbol(inventItemPurchSetup.METPurchUnit)
            && unitOfMeasureConversion.ToUnitOfMeasure      == UnitOfMeasure::unitOfMeasureIdBySymbol(inventTable.inventUnitId());

    if (unitOfMeasureConversion.Factor)
    {
        purchQty = _inventQty/unitOfMeasureConversion.Factor;
    }
    else
    {
        purchQty = _inventQty;
    }

    return purchQty;
}

/// <summary>
/// Event handler to react on a filter change.
/// </summary>
public void onFilterChanged()
{
    InventSum_ds.research();
    InventSum_ds.executeQuery();
}

 //Returns the current ItemId filter value
public ItemId parmItemIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmSourceFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(ItemId));

}

public void init()
{
    needsNonNetExpiredBatchUpdate = false;
    caller1 = element.args().caller() as FormRun;

    super();
    reserveOnOrdered            = InventParameters::find().ReserveOnOrdered;
    inventAvailabilityFormCache = InventAvailabilityFormCache::construct();

    QueryBuildDataSource qbdsUserWarehouse;
    qbdsUserWarehouse = InventDim_ds.queryBuildDataSource().addDataSource(tableNum(METAllowedWarehousesForISPUsers));
    qbdsUserWarehouse.joinMode(JoinMode::ExistsJoin);
    qbdsUserWarehouse.addLink(fieldnum(InventDim, InventLocationId), fieldNum(METAllowedWarehousesForISPUsers, InventLocationID));
    qbdsUserWarehouse.addRange(fieldnum(METAllowedWarehousesForISPUsers, UserId)).value(curUserId());
    InventDim_ds.executeQuery();
}

/// <summary>
/// Register the data source to which the filter should be applied.
/// </summary>
public void registerDatasourceOnQueryingEvent()
{
    InventSum_ds.OnQueryExecuting += eventhandler(this.parmFilterFormQueryEventHandler().applyFilter);
}

public void executeQuery()
{
    needsNonNetExpiredBatchUpdate = true;

    inventAvailabilityFormCache.refreshCache();            
    super();
    ItemId itemIdFilter;
    InventLocationId inventLocationIdFilter;

    if (caller1)
    {
        itemIdFilter = caller1.parmItemId();
        inventLocationIdFilter = caller1.parminventoryLocationId();
        this.query().dataSourceTable(tableNum(InventSum)).clearRanges();
        QueryBuildDataSource  qbds = this.queryBuildDataSource();
        if (inventLocationIdFilter)
        {

            qbds.addRange(fieldNum(InventSum, ItemId)).value(itemIdFilter);
            qbds.addRange(fieldNum(InventSum, InventLocationId)).value(inventLocationIdFilter);
            qbds.addRange(fieldNum(InventSum, Closed)).value(queryValue(NoYes::No));
        }
        else
        {
            qbds.addRange(fieldNum(InventSum, ItemId)).value(itemIdFilter);
            qbds.addRange(fieldNum(InventSum, Closed)).value(queryValue(NoYes::No));
            qbds.clearRange(fieldNum(InventSum, InventLocationId));
        }
        qbds.addRange(fieldNum(InventSum, ItemId)).status(RangeStatus::Locked);
        qbds.addRange(fieldNum(InventSum, InventLocationId)).status(RangeStatus::Locked);

    }
    super();

}

